source='''def transform(grid):
    height, width = len(grid), len(grid[0])
    cells_by_color = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                cells_by_color.setdefault(color, []).append((r, c))
    if 8 not in cells_by_color:
        return [row[:] for row in grid]
    anchor = cells_by_color[8]
    anchor_top = min(r for r, _ in anchor)
    anchor_left = min(c for _, c in anchor)
    anchor_shape = {(r - anchor_top, c - anchor_left) for r, c in anchor}
    out = [[0] * width for _ in range(height)]
    placed = set()
    for r, c in anchor:
        out[r][c] = 8
        placed.add((r, c))
    for color, cells in cells_by_color.items():
        if color == 8:
            continue
        top = min(r for r, _ in cells)
        left = min(c for _, c in cells)
        shape = {(r - top, c - left) for r, c in cells}
        target_top = anchor_top
        if shape != anchor_shape:
            # Keep a nonmatching object as close to the anchor as possible without overlap.
            direction = 1 if top > anchor_top else -1
            candidates = range(anchor_top, height) if direction == 1 else range(anchor_top, -1, -1)
            target_top = top
            for candidate in candidates:
                coords = {(candidate + r - top, c) for r, c in cells}
                if all(0 <= r < height and (r, c) not in placed for r, c in coords):
                    target_top = candidate
                    break
        offset = target_top - top
        for r, c in cells:
            out[r + offset][c] = color
            placed.add((r + offset, c))
    return out
'''
