source='''def transform(grid):
    height, width = len(grid), len(grid[0])
    cells_by_color = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                cells_by_color.setdefault(color, []).append((r, c))
    if 8 not in cells_by_color:
        return [row[:] for row in grid]
    anchor_top = min(r for r, _ in cells_by_color[8])
    moved = {}
    for color, cells in cells_by_color.items():
        offset = anchor_top - min(r for r, _ in cells)
        moved[color] = {(r + offset, c) for r, c in cells}
    # Resolve a collision by shifting the left-hand object one column left.
    colors = list(cells_by_color)
    occupied = {}
    out = [[0] * width for _ in range(height)]
    for color in colors:
        coords = moved[color]
        if any((r, c) in occupied for r, c in coords):
            coords = {(r, c - 1) for r, c in coords}
        for r, c in coords:
            if 0 <= c < width:
                out[r][c] = color
                occupied[(r, c)] = color
    return out
